const fs=require('fs'), path=require('path');
const HOME='C:/Users/eric_rash';
const roots=[HOME+'/.claude/skills', HOME+'/.claude/plugins'];
let found=[];
function walk(d,depth){
  if(depth>5) return;
  let ents; try{ents=fs.readdirSync(d,{withFileTypes:true});}catch(e){return;}
  for(const e of ents){
    const p=path.join(d,e.name);
    if(e.name==='SKILL.md'){found.push(p); continue;}
    if(e.isDirectory()||e.isSymbolicLink()){
      if(e.name==='node_modules'||e.name==='.git') continue;
      walk(p,depth+1);
    }
  }
}
for(const r of roots) walk(r,0);
console.log('SKILL.md files found:', found.length);
// sample roots
const byRoot={};
for(const f of found){ const k=f.includes('plugins')?'plugins':'skills'; byRoot[k]=(byRoot[k]||0)+1;}
console.log(byRoot);
// parse frontmatter of a few
let parsed=0, descLens=[];
for(const f of found){
  try{
    const t=fs.readFileSync(f,'utf8');
    const m=t.match(/^---\r?\n([\s\S]*?)\r?\n---/);
    if(!m) continue;
    const fm=m[1];
    const nm=fm.match(/^name:\s*(.+)$/m);
    const ds=fm.match(/^description:\s*([\s\S]*?)(?=\n[a-zA-Z_-]+:|$)/m);
    if(nm&&ds){parsed++; descLens.push(ds[1].trim().length);}
  }catch(e){}
}
console.log('parsed name+description:', parsed);
descLens.sort((a,b)=>a-b);
console.log('desc chars: total', descLens.reduce((a,b)=>a+b,0), 'median', descLens[Math.floor(descLens.length/2)], 'max', descLens[descLens.length-1]);

