#!/usr/bin/env python3
"""Build roster.json: every skill this machine can invoke, with the text Jev ranks on.

Run this offline, whenever skills change. The hook never walks the filesystem; it
reads the JSON this writes. Stdlib only, so it runs under any Python on either box.

Name derivation is the part that matters. A suggestion Claude cannot invoke is worse
than no suggestion, so the `name` field here must be the *invocable* name:

  ~/.claude/skills/<dir>/SKILL.md                              -> <frontmatter name>
  ~/.claude/plugins/cache/<mkt>/<plugin>/skills/**/SKILL.md    -> <plugin>:<frontmatter name>
  ~/.claude/plugins/synced/<bucket>/<plugin>/skills/**/SKILL.md-> <plugin>:<frontmatter name>

Plugins disabled in settings.json are skipped. Synced plugins carry no enable flag
there (they arrive from the managed bucket already enabled), so they are always kept.

Usage:
    python build_roster.py                 # write roster.json next to this file
    python build_roster.py --check         # report coverage vs expected_skills.txt
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys
from pathlib import Path

HOME = Path(os.path.expanduser("~"))
CLAUDE = HOME / ".claude"
HERE = Path(__file__).resolve().parent
ROSTER_PATH = HERE / "roster.json"
EXPECTED_PATH = HERE / "expected_skills.txt"

# How much of each SKILL.md body the reranker is allowed to read per candidate.
# The cookbook's own value was stripped out of the mirrored page (see README), so this
# is our choice, not theirs: 3 candidates x 1200 chars keeps request 2 well inside the
# 32k-token state budget while still showing what each skill actually does.
BODY_EXCERPT = 1200

FRONTMATTER = re.compile(r"\A---\r?\n(.*?)\r?\n---\r?\n?", re.DOTALL)


def parse_frontmatter(text: str) -> tuple[dict, str]:
    """Return (frontmatter dict, body). Only the scalar keys we need are parsed."""
    match = FRONTMATTER.match(text)
    if not match:
        return {}, text
    block, body = match.group(1), text[match.end():]
    fields: dict[str, str] = {}
    key = None
    for line in block.splitlines():
        header = re.match(r"^([A-Za-z0-9_-]+):\s*(.*)$", line)
        if header:
            key = header.group(1)
            fields[key] = header.group(2).strip()
        elif key and line.strip():
            # a folded continuation line of the previous key
            fields[key] = (fields[key] + " " + line.strip()).strip()
    for key, value in fields.items():
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
            fields[key] = value[1:-1]
    return fields, body


def enabled_plugins() -> dict[str, bool]:
    """Merge the enabledPlugins maps, keyed by bare plugin name."""
    flags: dict[str, bool] = {}
    for filename in ("settings.json", "settings.local.json"):
        path = CLAUDE / filename
        if not path.exists():
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (ValueError, OSError):
            continue
        for qualified, on in (data.get("enabledPlugins") or {}).items():
            flags[qualified.split("@", 1)[0]] = bool(on)
    return flags


def skill_files(root: Path) -> list[Path]:
    if not root.is_dir():
        return []
    found = []
    for dirpath, dirnames, filenames in os.walk(root, followlinks=True):
        dirnames[:] = [d for d in dirnames if d not in (".git", "node_modules")]
        if "SKILL.md" in filenames:
            found.append(Path(dirpath) / "SKILL.md")
    return found


def record(path: Path, prefix: str | None) -> dict | None:
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None
    fields, body = parse_frontmatter(text)
    bare = (fields.get("name") or path.parent.name).strip()
    description = " ".join((fields.get("description") or "").split())
    if not bare or not description:
        return None
    name = f"{prefix}:{bare}" if prefix else bare
    # The index line Jev ranks on in request 1. Kept short on purpose: 189 of these
    # share one request's state budget, and context rot is the documented failure.
    short = description if len(description) <= 200 else description[:197] + "..."
    return {
        "name": name,
        "description": short,
        "description_full": description,
        "body": " ".join(body.split())[:BODY_EXCERPT],
        "source": str(path),
    }


def collect() -> tuple[list[dict], list[str]]:
    flags = enabled_plugins()
    skills: dict[str, dict] = {}
    skipped: list[str] = []

    for path in skill_files(CLAUDE / "skills"):
        entry = record(path, None)
        if entry:
            skills.setdefault(entry["name"], entry)

    plugins_root = CLAUDE / "plugins"
    # cache/<marketplace>/<plugin>/...  and  synced/<bucket>/<plugin>/...
    for container, honour_flags in (("cache", True), ("synced", False)):
        base = plugins_root / container
        if not base.is_dir():
            continue
        for middle in sorted(p for p in base.iterdir() if p.is_dir()):
            for plugin_dir in sorted(p for p in middle.iterdir() if p.is_dir()):
                plugin = plugin_dir.name
                if honour_flags and flags.get(plugin) is False:
                    skipped.append(plugin)
                    continue
                for path in skill_files(plugin_dir):
                    entry = record(path, plugin)
                    if entry:
                        skills.setdefault(entry["name"], entry)

    return sorted(skills.values(), key=lambda s: s["name"]), sorted(set(skipped))


def check(roster: list[dict]) -> int:
    """Compare against the names Claude Code actually offered, if we captured them."""
    if not EXPECTED_PATH.exists():
        print(f"no {EXPECTED_PATH.name}; skipping coverage check")
        return 0
    expected = {
        line.strip()
        for line in EXPECTED_PATH.read_text(encoding="utf-8").splitlines()
        if line.strip() and not line.startswith("#")
    }
    have = {s["name"] for s in roster}
    missing = sorted(expected - have)
    extra = sorted(have - expected)
    print(f"expected {len(expected)} invocable skills, roster has {len(have)}")
    print(f"  matched: {len(expected & have)}")
    print(f"  missing from roster ({len(missing)}): {', '.join(missing) or 'none'}")
    print(f"  in roster but not offered ({len(extra)}): {', '.join(extra[:25]) or 'none'}")
    if len(extra) > 25:
        print(f"    ... and {len(extra) - 25} more")
    return 1 if missing else 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="coverage report only")
    args = parser.parse_args()

    roster, skipped = collect()
    if not args.check:
        ROSTER_PATH.write_text(
            json.dumps(roster, indent=1, ensure_ascii=False), encoding="utf-8"
        )

    index_chars = sum(len(s["name"]) + len(s["description"]) + 6 for s in roster)
    print(f"{len(roster)} skills")
    print(f"index for request 1: ~{index_chars:,} characters (~{index_chars // 4:,} tokens)")
    print(f"disabled plugins skipped: {', '.join(skipped) or 'none'}")
    if not args.check:
        print(f"wrote {ROSTER_PATH}")
    if len(roster) > 240:
        print(
            f"WARNING: {len(roster)} options exceeds the ~240 where Choice reliability "
            "drops (255 hard cap). Split the ranking into chunks.",
            file=sys.stderr,
        )
    return check(roster) if args.check else 0


if __name__ == "__main__":
    sys.exit(main())

