#!/usr/bin/env python3
"""Build roster.json: every skill this machine can invoke, with the text Jev ranks on.

Run this offline, whenever skills change. The hook never walks the filesystem; it
reads the JSON this writes. Stdlib only, so it runs under any Python on either box.

Name derivation is the part that matters. A suggestion Claude cannot invoke is worse
than no suggestion, so `name` here must be the *invocable* name:

  ~/.claude/skills/<dir>/SKILL.md                                -> <frontmatter name>
  ~/.claude/skills/synced/<bucket>/<dir>/SKILL.md                -> anthropic-skills:<name>
  ~/.claude/plugins/cache/<mkt>/<plugin>/**/skills/**/SKILL.md   -> <plugin>:<name>
  ~/.claude/plugins/synced/<bucket>/<plugin>/**/skills/**/SKILL.md -> <plugin>:<name>

Two safety nets, because the mapping above is inferred from disk layout and the
layout is not ours:

  * plugins disabled in settings.json are skipped, keyed on <plugin>@<marketplace>
    (two marketplaces ship a plugin called `mattpocock-skills`, one enabled and one
    not, so the bare name is ambiguous);
  * if expected_skills.txt exists it acts as an ALLOW-LIST. Anything discovered but
    not listed there is dropped. That is what guarantees every name the router can
    suggest is a name Claude can actually invoke.

supplemental.json supplies the skills that have no SKILL.md on disk at all: the ones
built into Claude Code, and plugin commands.

Usage:
    python build_roster.py                 # write roster.json next to this file
    python build_roster.py --check         # coverage report, writes nothing
    python build_roster.py --no-allowlist  # keep everything found (diagnostic)
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys
from pathlib import Path

HOME = Path(os.path.expanduser("~"))
CLAUDE = HOME / ".claude"
HERE = Path(__file__).resolve().parent
ROSTER_PATH = HERE / "roster.json"
EXPECTED_PATH = HERE / "expected_skills.txt"
SUPPLEMENTAL_PATH = HERE / "supplemental.json"

# How much of each SKILL.md body the reranker may read per candidate. The cookbook's
# own value was stripped out of the mirrored page (see docs/vendor/typesafe/README.md),
# so this is our choice, not theirs: 3 candidates x 1200 chars keeps request 2 well
# inside the 32k-token state budget while still showing what each skill actually does.
BODY_EXCERPT = 1200

# The harness surfaces the synced skills bucket under this plugin name. The bucket's
# own manifest.json calls the source "anthropic-example", so the name is not derivable
# from disk; it comes from the available-skills listing. The allow-list catches a drift.
SYNCED_SKILLS_PLUGIN = "anthropic-skills"

FRONTMATTER = re.compile(r"\A---\r?\n(.*?)\r?\n---\r?\n?", re.DOTALL)


def parse_frontmatter(text: str) -> tuple[dict, str]:
    """Return (frontmatter dict, body). Only scalar keys are parsed."""
    match = FRONTMATTER.match(text)
    if not match:
        return {}, text
    block, body = match.group(1), text[match.end():]
    fields: dict[str, str] = {}
    key = None
    for line in block.splitlines():
        header = re.match(r"^([A-Za-z0-9_-]+):\s*(.*)$", line)
        if header:
            key = header.group(1)
            fields[key] = header.group(2).strip()
