#!/usr/bin/env python3
"""UserPromptSubmit hook: suggest at most one skill for the prompt, using Jev.

Implements the TypeSafe `skill_suggestion` cookbook against our own roster. Two
requests: one ranks all 144 skills and asks whether the turn wants a skill at all,
one re-reads the top three with real detail and may reject all of them.

THE OPERATING CONSTRAINT: this runs in front of every prompt Eric types. A network
call in the hot path is exactly the failure class the memsearch hook is already in.
So:

  * one hard deadline (SKILL_ROUTER_BUDGET, default 2.0s) covering BOTH calls, not a
    timeout per call;
  * no retries, ever;
  * every failure path prints nothing and exits 0. A broken router must be invisible,
    never a blocked or delayed prompt;
  * the whole of main() is inside one try/except.

Exit codes matter here: 0 means the prompt proceeds and stdout is added as context.
This script never exits non-zero, because exit 2 on UserPromptSubmit blocks the prompt.

Stdlib only and no venv, so the same file runs on the Mac and the Windows box.

Read from stdin (JSON, as Claude Code sends it):
    {"session_id": "...", "prompt": "...", "cwd": "..."}

Test it by hand:
    echo '{"prompt":"build my status report"}' | python router.py
    python router.py --explain "build my status report"     # show the workings
"""

from __future__ import annotations

import json
import os
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path

ENDPOINT = "https://api.typesafe.ai/v1/systemone"
MODEL = os.environ.get("SKILL_ROUTER_MODEL", "jev-latest")

HERE = Path(__file__).resolve().parent
ROSTER_PATH = Path(os.environ.get("SKILL_ROUTER_ROSTER", HERE / "roster.json"))
LOG_PATH = Path(
    os.environ.get("SKILL_ROUTER_LOG", Path(os.path.expanduser("~")) / ".claude" / "skill_router.log")
)

# Total wall-clock budget for both requests plus TLS setup. The cookbook measured
# ~110ms per call; 2s leaves room for a cold connection and still bounds the damage.
BUDGET = float(os.environ.get("SKILL_ROUTER_BUDGET", "2.0"))

# From the cookbook's prose. The config cell that held them was stripped from the
# mirrored page, so these are the values it states in text, not copied constants.
GATE_THRESHOLD = 0.30   # mean of the three oriented gate nouls, below which: stay quiet
SHORTLIST = 3           # candidates carried into request 2
FITS_THRESHOLD = 0.30   # best `fits` noul, below which: nothing fits

# Only the opening of the prompt is sent. Two reasons: accuracy falls as the state
# grows with irrelevant content (documented context rot), and a pasted table should
# not travel to a third-party API in its entirety. See the governance note in README.
PROMPT_CHARS = 500

# Below this, a prompt is an acknowledgement ("yes", "go on") and never wants a skill.
MIN_PROMPT_CHARS = 15

CHOICE_INSTRUCTIONS = (
    "Which of these skills, if any, is the right one to load to help with the "
    "user's latest request?"
)
RERANK_INSTRUCTIONS = (
    "Exactly one of these skills is the right one to load for the user's latest "
    "request. Which one? Read what each actually does, not just its name."
)
GATE_QUESTIONS = {
    "acts_on_user_system": (
        "Is the assistant being asked to act on the user's files, accounts, devices, "
        "or online services, rather than only to explain or advise?"
    ),
    "would_follow_documented_procedure": (
        "Would a careful expert answering this consult a specific documented procedure "
        "or set of commands, rather than answering from general understanding?"
    ),
    "prose_suffices": (
        "Could a knowledgeable generalist fully satisfy this request in prose, with "
        "no tools, no documentation, and no access to the user's files or accounts?"
    ),
}
INVERTED = {"prose_suffices"}  # a yes here points away from needing a skill


def log(status: str, millis: int, detail: str = "") -> None:
    """One line per invocation. This is how the timeout rate becomes visible."""
    try:
        LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        stamp = time.strftime("%Y-%m-%dT%H:%M:%S")
        with LOG_PATH.open("a", encoding="utf-8") as handle:
            handle.write(f"{stamp}\t{status}\t{millis}ms\t{detail}\n")
    except OSError:
        pass


def api_key() -> str | None:
    """Env var first, then the file. Hooks inherit Claude Code's launch environment,
    which on the Mac may not carry the Keychain export, so the file is the fallback."""
    key = os.environ.get("TYPESAFE_API_KEY")
    if key and key.strip():
        return key.strip()
    env_file = Path(os.path.expanduser("~")) / ".claude" / "typesafe.env"
    try:
        for line in env_file.read_text(encoding="utf-8").splitlines():
            name, _, value = line.strip().partition("=")
            if name.strip() == "TYPESAFE_API_KEY" and value.strip():
                return value.strip().strip("\"'")
    except OSError:
        pass
    return None


def ask(questions: dict, state: dict, key: str, deadline: float) -> dict:
    """One request. Raises if the remaining budget is already gone."""
    remaining = deadline - time.monotonic()
    if remaining <= 0.05:
        raise TimeoutError("budget exhausted")
    body = json.dumps(
        {"state": state, "model": MODEL, "questions": questions}
    ).encode("utf-8")
    request = urllib.request.Request(
        ENDPOINT,
        data=body,
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=remaining) as response:
        return json.loads(response.read().decode("utf-8"))


def rank_wide(roster: list[dict], state: dict, key: str, deadline: float) -> dict:
    """Request 1: rank every skill, and gate on whether a skill is wanted at all."""
    questions = {
        "which": {
            "type": "choice",
            "instructions": CHOICE_INSTRUCTIONS,
            "criteria": {s["name"]: s["description"] for s in roster},
        }
    }
    for name, text in GATE_QUESTIONS.items():
        questions[f"gate::{name}"] = {"type": "noul", "instructions": text}

    answers = ask(questions, state, key, deadline)["answers"]
    probabilities = answers["which"].get("probabilities") or {}
    ranked = sorted(probabilities.items(), key=lambda kv: -kv[1])[:12]
    values = {
        name.removeprefix("gate::"): answer.get("noul", 0.0)
        for name, answer in answers.items()
        if name.startswith("gate::")
    }
    oriented = [(1.0 - v) if k in INVERTED else v for k, v in values.items()]
    return {
        "ranked": ranked,
        "gate": sum(oriented) / len(oriented) if oriented else 0.0,
        "values": values,
    }


def rerank(
    candidates: list[dict], state: dict, key: str, deadline: float
) -> dict:
    """Request 2: the same Choice over three candidates, now with real detail,
    plus one absolute noul per candidate so the shortlist can be rejected whole."""
    questions = {
        "which": {
            "type": "choice",
            "instructions": RERANK_INSTRUCTIONS,
            "criteria": {
                s["name"]: (
                    f"{s['description_full']} - {s['body']}" if s["body"]
                    else s["description_full"]
                )
                for s in candidates
            },
        }
    }
    for skill in candidates:
        questions[f"fits::{skill['name']}"] = {
            "type": "noul",
            "instructions": (
                f"Does the skill '{skill['name']}' do the specific thing the user's "
                f"request asks for? It is described as: {skill['description_full']}"
            ),
        }

    answers = ask(questions, state, key, deadline)["answers"]
    return {
        "winner": answers["which"].get("choice"),
        "confidence": answers["which"].get("confidence"),
        "fits": {
            name.removeprefix("fits::"): answer.get("noul", 0.0)
            for name, answer in answers.items()
            if name.startswith("fits::")
        },
    }


def suggest(prompt: str, roster: list[dict], key: str, deadline: float) -> tuple[tuple[str, ...], dict]:
    """At most one skill name, or () for 'nothing here applies'."""
    by_name = {s["name"]: s for s in roster}
    state = {"request": prompt[:PROMPT_CHARS], "recent_context": ""}

    wide = rank_wide(roster, state, key, deadline)
    trace = {"gate": wide["gate"], "values": wide["values"], "ranked": wide["ranked"][:5]}
    if wide["gate"] < GATE_THRESHOLD:
        trace["stopped"] = "gate"
        return (), trace

    candidates = [by_name[n] for n, _ in wide["ranked"][:SHORTLIST] if n in by_name]
    if not candidates:
        trace["stopped"] = "no candidates"
        return (), trace

    result = rerank(candidates, state, key, deadline)
    trace["fits"] = result["fits"]
    trace["winner"] = result["winner"]
    if not result["fits"] or max(result["fits"].values()) < FITS_THRESHOLD:
        trace["stopped"] = "fits"
        return (), trace
    if result["winner"] not in by_name:
        trace["stopped"] = "winner not in roster"
        return (), trace
    return (result["winner"],), trace


def suggestion_block(names: tuple[str, ...]) -> str:
    """The wording is the cookbook's, verbatim, and deliberately easy to ignore.

    Pushing harder wins compliance on the wrong suggestions too, and a wrong
    suggestion is worse than none. The empty case still says something, because
    the superpowers rule already in this harness ("if there is even a 1% chance a
    skill might apply ... you MUST invoke the skill") is the same pressure the
    cookbook's Hermes roster applied with "err on the side of loading". Silence
    would leave it unopposed.
    """
    if names:
        body = (
            f"Relevant to the current request: {', '.join(names)}. Ignore this if it "
            "does not fit what the user actually asked for."
        )
    else:
        body = "No skill in the roster appears relevant to this request."
    return f"<skill_relevance>\n{body}\n</skill_relevance>"


def load_roster() -> list[dict]:
    data = json.loads(ROSTER_PATH.read_text(encoding="utf-8"))
    return [s for s in data if s.get("name") and s.get("description")]


def run(prompt: str, explain: bool = False) -> int:
    started = time.monotonic()
    deadline = started + BUDGET

    prompt = (prompt or "").strip()
    if len(prompt) < MIN_PROMPT_CHARS or prompt.startswith("/"):
        # A slash command already names its skill; an acknowledgement never wants one.
        log("skip", 0, f"len={len(prompt)}")
        return 0

    key = api_key()
    if not key:
        log("skip", 0, "no key")
        return 0

    try:
        roster = load_roster()
    except (OSError, ValueError) as error:
        log("error", 0, f"roster: {type(error).__name__}")
        return 0
    if not roster:
        log("skip", 0, "empty roster")
        return 0

    names, trace = suggest(prompt, roster, key, deadline)
    millis = int((time.monotonic() - started) * 1000)
    log("ok", millis, f"{names[0] if names else 'none'} gate={trace.get('gate', 0):.2f}")

    if explain:
        print(json.dumps(trace, indent=1))
        print(f"\n[{millis}ms]")
    print(suggestion_block(names))
    return 0


def main() -> int:
    if len(sys.argv) > 2 and sys.argv[1] == "--explain":
        return run(sys.argv[2], explain=True)
    try:
        payload = json.loads(sys.stdin.read() or "{}")
    except ValueError:
        log("error", 0, "bad stdin json")
        return 0
    return run(payload.get("prompt") or payload.get("user_prompt") or "")


if __name__ == "__main__":
    # One net that catches everything, including what the inner handlers missed.
    # A router that fails loudly is worse than no router at all.
    try:
        sys.exit(main())
    except BaseException as error:  # noqa: BLE001 - deliberate: never fail a prompt
        try:
            log("error", 0, type(error).__name__)
        except Exception:
            pass
        sys.exit(0)

