def ask(questions: dict, state: dict, key: str, deadline: float) -> dict:
    """One request, bounded by real wall-clock time. Raises if the budget is gone.

    `urlopen(timeout=)` does NOT bound total time. It bounds each individual blocking
    socket operation, so DNS, connect, TLS, headers and every body read each get the
    full timeout, and a server trickling bytes can hold the connection open forever
    while never once exceeding a single read's timeout. That is unacceptable here,
    where the whole point is that the hook cannot delay a prompt.

    So the request runs on a daemon thread and we join with the remaining budget. If
    it has not finished by then we abandon it and raise. Abandoning is safe precisely
    because the thread is a daemon: the interpreter exits without waiting for it, so
    a wedged socket cannot outlive the hook. The socket timeout is still passed as a
    second line of defence for the common slow-connect case.
    """
    remaining = deadline - time.monotonic()
    if remaining <= 0.05:
        raise TimeoutError("budget exhausted")

    body = json.dumps(
        {"state": state, "model": MODEL, "questions": questions}
    ).encode("utf-8")
    request = urllib.request.Request(
        ENDPOINT,
        data=body,
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )

    outcome: dict = {}

    def perform() -> None:
        try:
            with urllib.request.urlopen(request, timeout=remaining) as response:
                raw = response.read(MAX_RESPONSE_BYTES)
            outcome["data"] = json.loads(raw.decode("utf-8"))
        except BaseException as error:  # noqa: BLE001 - carried back to the caller
            outcome["error"] = error

    worker = threading.Thread(target=perform, daemon=True)
    worker.start()
    worker.join(remaining)
    if worker.is_alive():
        raise TimeoutError("wall-clock budget exceeded")
    if "error" in outcome:
        raise outcome["error"]
    if "data" not in outcome:
        raise ValueError("no response")
    return outcome["data"]

