const fs=require('fs');
const rows=JSON.parse(fs.readFileSync('C:/Users/eric_rash/.claude/jobs/985549de/tmp/brief.json','utf8'));
console.log(`${rows.length} claims extracted\n`);
const targets={
 'misquote 1 Kamarajugadda (pitch volume)':'pitch volume',
 'misquote 2 Takaba (scalene stiffness)':'scalene stiffness',
 'misquote 3 Ulman (distraction variance)':'distraction variance',
};
for(const [name,needle] of Object.entries(targets)){
  const hits=rows.filter(r=>r.claim.toLowerCase().includes(needle));
  console.log(`${name} -> ${hits.length} matching claim(s)`);
  hits.forEach(h=>{
    console.log(`   verdict=${h.verdict}  choice=${h.choice}  conf=${h.confidence}`);
    console.log(`   claim: ${h.claim.slice(0,140)}`);
  });
  if(!hits.length) console.log('   NOT EXTRACTED AS A CLAIM');
  console.log();
}
// how many flagged claims are actually questions?
const q=rows.filter(r=>r.claim.includes('?'));
console.log(`claims containing a question mark: ${q.length} (category error - questions assert nothing)`);
const qflag=q.filter(r=>['overstated','unsupported'].includes(r.verdict));
console.log(`  of those, flagged as overstated/unsupported: ${qflag.length}`);

